from ansible.module_utils.facts.sysctl import get_sysctl


class FakeModule:
    def __init__(self, output=None, rc=0, error=None):
        self.output = output
        self.rc = rc
        self.error = error
        self.commands = []
        self.warnings = []

    def get_bin_path(self, name):
        assert name == "sysctl"
        return "/sbin/sysctl"

    def run_command(self, command):
        self.commands.append(command)
        if self.error is not None:
            raise self.error
        return self.rc, self.output, ""

    def warn(self, message):
        self.warnings.append(message)


def test_get_sysctl_parses_blank_multiline_colon_equals_and_malformed_lines():
    module = FakeModule(
        output=(
            "kernel.first = one\n"
            " continuation line\n"
            "\n"
            "kernel.second: two\n"
            "malformed line\n"
            "kernel.third=three\n"
        )
    )

    result = get_sysctl(module, ["kernel.first", "kernel.second"])

    assert module.commands == [
        ["/sbin/sysctl", "kernel.first", "kernel.second"]
    ]
    assert result == {
        "kernel.first": "one\n continuation line",
        "kernel.second": "two",
        "kernel.third": "three",
    }
    assert len(module.warnings) == 1
    assert "Unable to split sysctl line (malformed line)" in module.warnings[0]


def test_get_sysctl_warns_and_returns_empty_mapping_when_command_fails():
    module = FakeModule(error=OSError("sysctl unavailable"))

    result = get_sysctl(module, ["kernel"])

    assert module.commands == [["/sbin/sysctl", "kernel"]]
    assert result == {}
    assert module.warnings == [
        "Unable to read sysctl: sysctl unavailable"
    ]


def test_get_sysctl_returns_empty_mapping_for_nonzero_return_code():
    module = FakeModule(output="kernel.value = ignored\n", rc=1)

    result = get_sysctl(module, [])

    assert module.commands == [["/sbin/sysctl"]]
    assert result == {}
    assert module.warnings == []
